    var maxBananas = 0L
    for (y in 0..b) {
        val x = m * (b - y)
        val n = x + 1
        val sumX = n * (n - 1) / 2
        val sumY = (y + 1) * y / 2
        val total = sumX * (y + 1) + sumY * (x + 1)
        if (total > maxBananas) maxBananas = total
    }
    println(maxBananas)
}
